 public static void rebuild(Object s){R.call(s,"clearWidgets");((java.util.List<?>)R.get(s,"inputs")).clear();((java.util.List<?>)R.get(s,"inputTargets")).clear();R.set(s,"manual",false);int size=((Number)R.call(s,"gridSize")).intValue(),x=((Number)R.call(s,"gridStartX")).intValue()+size*13+scale(s,18),width=n(s,"panelX")+n(s,"panelWidth")-scale(s,18)-x;Object name=R.make("net.minecraft.client.gui.components.EditBox",R.get(s,"font"),x,n(s,"panelY")+scale(s,45),width,scale(s,18),Component.literal("Objetivo"));R.call(name,"setValue","Captura de territorio");R.set(s,"nameBox",name);int bottom=n(s,"panelY")+n(s,"panelHeight")-scale(s,60);Button.OnPress launch=b->R.call(s,"submit",false),back=b->R.call(R.get(s,"minecraft"),"setScreen",new ClanScreen());for(int i=0;i<2;i++){Object button=R.make("me.danialisntcool.factionfriction.client.ui.ModernButton",x,bottom+scale(s,i*24),width,scale(s,18),Component.literal(i==0?"Capturar selección":"Volver"),i==0?launch:back,0xff282a22,0xff424838);R.call(s,"addRenderableWidget",button);}}
 public static void render(Object screen,Object graphics){int size=((Number)R.call(screen,"gridSize")).intValue(),x=((Number)R.call(screen,"gridStartX")).intValue()+size*13+scale(screen,18),y=n(screen,"panelY")+scale(screen,45);String[] land=ClientClans.one("LAND"),config=ClientClans.one("CONFIG");String[] lines={"1. Marca un chunk enemigo.","2. Pulsa Capturar selección.","Debe estar en la frontera.","Preparación: "+(config==null?"5":config[1])+" min.","Un defensor debe estar conectado.",land==null?"":"Territorio: "+land[2]+" / "+land[3],"Rompe "+(config==null||config.length<6?"50":config[3])+" bloques del objetivo.","Controla "+(config==null||config.length<6?"60":config[4])+" s sin defensor dentro.","Defiende "+(config==null||config.length<6?"120":config[5])+" s sin atacantes dentro."};for(String line:lines){R.call(graphics,"drawString",R.get(screen,"font"),line,x,y,0xffd3d5bf,false);y+=scale(screen,13);}}
